from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
def A(h,w,m):return h+[[w,m]]
B=[['希腊 dunasthai → dunamis（δύναμις）','能够、有力量 → 力量、能力']]
DYNAMIC=B+[['希腊 dunamikos → 法语学术用语 dynamique','有力量的 → 近代力学中的动力相关的'],['英语 dynamic','动力的；后来又说有活力、变化中的']]
DYNAMICS=B+[['希腊 dunamikos → 法语学术用语 dynamique','力量相关的 → 研究力与运动'],['英语学科名 dynamics','采用 dynam- 与学科词尾 -ics；后来也指互动、变化机制']]
DYNASTY=[['希腊 dunasthai → dunastes → dunasteia','有能力、掌权 → 统治者 → 权势、统治'],['晚期／中世纪拉丁 dynastia；法语 dynastie','统治权；统治者的接续'],['英语 dynasty','同一家族相继统治；引申为长期居领先地位的家族或团队']]
AERO=DYNAMICS+[['英语 aero- + dynamics → aerodynamics','把空气、气流作为研究对象']]
AERODYN=A(AERO,'英语 aerodynamic，构件 aero- + dynamic','与气流及其作用力有关的；也说有利于减小空气阻力的外形')
THERMO=[['希腊 therme + dunamikos','热 + 力量相关的'],['英语 thermo- + dynamic → thermodynamic','热与能量、做功等关系中的']]
HYDRO=[['希腊 hudor（水）与 dunamis（力量）的构词成分','hydro- 与 dynam-'],['近代拉丁 hydrodynamica → 英语 hydrodynamics','研究流动的流体及其作用力']]
NASA='https://www.nasa.gov/learning-resources/for-kids-and-students/what-is-aerodynamics-grades-5-8/'
HEAT='https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/heat-transfer-3/'
MIT='https://www.ocw.mit.edu/courses/2-016-hydrodynamics-13-012-fall-2005/'
W=[
E('dynamic','/daɪˈnæmɪk/','有活力的；不断变化的；动力的；互动模式〔名词〕','人有推动事情的劲头，环境一直在变化；说一群人的 dynamic，则是在看他们怎样互相影响。','经法语 dynamique 接希腊 dunamikos“有力量的”，远接 dunamis“力量”。先是力学用词，再发展日常比喻；名词用法从形容词转来。',DYNAMIC,'a dynamic leader 往往积极、有带动能力；a dynamic market 说市场不停变化；the dynamic between two people 则是两人的互动模式，不一定融洽。计算机中的 dynamic 常与预先固定的 static 对照。','a dynamic team；a dynamic environment；the dynamic between；change the dynamic。','energetic 主要说精力充沛；dynamic 还能说变化过程与互动关系。dynamic pricing 是随条件调整价格，不是“有活力的价格”。',('The project needs a dynamic leader who can bring different teams together.','这个项目需要一位能把不同团队带动起来的负责人。'),('New technology is changing the dynamic between sellers and buyers.','新技术正在改变买卖双方的互动关系。'),('Small businesses have to adapt to a dynamic market.','小企业必须适应不断变化的市场。'),sources=[S('dynamic'),K('dynamic'),O('dynamic')]),
E('dynamics','/daɪˈnæmɪks/','动力学；互动与变化机制；音乐力度变化','一台机器为何这样动，一群人为何这样相处，一段音乐为何忽强忽弱：这个词看的是变化背后的作用关系。','学科词采用 dynam- + -ics，并参照法语 dynamique。英语 dynamics 的记录早于常见形容词 dynamic 的记录，因此不能把两者真实历史简化为给现代形容词加 s。',DYNAMICS,'物理课上的 dynamics 研究力与运动的关系；group dynamics 说群体成员如何互相影响；音乐中的 dynamics 说声音的强弱。作学科名时通常当单数：Dynamics is...。','group dynamics；family dynamics；market dynamics；the dynamics of；musical dynamics。','a dynamic 可指某一种互动模式；dynamics 常看整套作用关系。音乐里的 dynamics 说力度，tempo 说速度，这两者可以分别变化。',('The course introduces dynamics through the motion of a swinging pendulum.','这门课通过摆动的钟摆介绍动力学。'),('Adding a new manager changed the team’s dynamics.','新加入一位经理改变了团队内部的互动方式。'),('The conductor asked for greater contrast in the dynamics.','指挥要求音乐力度的强弱对比再鲜明些。'),sources=[M('dynamics'),K('dynamics'),O('dynamics'),S('dynamic')]),
E('dynamically','/daɪˈnæmɪkli/，也读 /daɪˈnæmɪkəli/','动态地；随条件变化地；富有活力地','事情并非从头到尾照一张固定表运行，而是随着输入、环境或进展继续调整。','dynamic + -ally，英语副词；承接 dynamic 的动力、变化或活力含义，要由所修饰的动作来定。',A(DYNAMIC,'英语 dynamic + -ally → dynamically','以动态、随变化调整或富有活力的方式'),'dynamically update information 是信息在使用过程中更新；dynamically allocate resources 是按当时需要分配资源。文艺评论中也可说表演充满活力。','dynamically generated；dynamically updated；dynamically allocate；respond dynamically。','automatically 强调不用人逐次手动处理；dynamically 强调随当时情况变化。一个自动运行但内容固定的程序，并非每一部分都是动态的。',('The dashboard updates dynamically as new orders arrive.','新订单进入时，仪表盘会动态更新。'),('The system allocates memory dynamically according to demand.','系统会根据需求动态分配内存。'),sources=[K('dynamically'),M('dynamic'),S('dynamic')]),
E('dynamical','/daɪˈnæmɪkəl/','动力学的；与系统随时间变化有关的','把注意力放在一个系统怎样从现在变成下一刻：钟摆怎样摆动、人口怎样变化，都可以进入这样的研究。','与 dynamic 同接希腊 dunamikos 和近代法语学术用语 dynamique 的学术背景；构形可看作 dynamic + -al。两种英语形容词在早期科学用语中并行，不能据今天较短的形式硬排先后。',B+[['希腊 dunamikos；近代法语 dynamique 的学术背景','力量、运动相关的'],['英语学术形容词 dynamical（-al）','与动力学或随时间变化的系统有关的']],'a dynamical system 常是按一定规律随时间演化的系统；a dynamical model 可以研究这类变化。它主要出现在数学、物理等语境，日常夸一个人有活力通常用 dynamic。','a dynamical system；a dynamical model；dynamical behaviour。','dynamic 与 dynamical 在一些技术搭配中都可用；dynamical 更像学术标签。a dynamic speaker 通常不能随意换成 a dynamical speaker。',('The pendulum is a simple example of a dynamical system.','钟摆是动力系统的一个简单例子。'),('The researchers built a dynamical model of population change.','研究者建立了一个描述人口变化的动力学模型。'),sources=[K('dynamical'),M('dynamical'),S('dynamic'),'https://ocw.mit.edu/courses/18-03-differential-equations-spring-2010/']),
E('dynamism','/ˈdaɪnəmɪzəm/','活力；推动变化的劲头','不仅在忙，还不断产生新主意、促成行动，让周围的事向前发展。','以希腊 dunamis“力量”为基础加 -ism；也能与英语 dynamic 对照理解。早期有哲学上的动力论用法，日常所说的活力是这条“力量、作用”意义的延伸。',B+[['近代学术构词 dynam- + -ism → dynamism','把力量、作用视为核心的思想用语'],['英语常用引申 dynamism','人的干劲；地方或组织的活力']],'the dynamism of a city 说城市不断发展、冒出新活动的劲头；a leader’s dynamism 说这个人能带动事情。它一般是不可数名词。','economic dynamism；creative dynamism；bring dynamism to；energy and dynamism。','dynamic 是形容词或互动模式名词；dynamism 是活力这一品质。忙碌不一定等于 dynamism，后者更带主动、推动发展的评价。',('New cafés and workshops have added to the neighbourhood’s dynamism.','新开的咖啡馆和工作室让这个街区更有活力。'),('Her dynamism helped turn a vague idea into a real project.','她的干劲帮助大家把一个模糊想法做成了实际项目。'),sources=[S('dynamism'),K('dynamism'),O('dynamism')]),
E('dynasty','英 /ˈdɪnəsti/；美 /ˈdaɪnəsti/','王朝；世代有权势的家族；长期领先的团队','接班的人一代接一代，权力或优势仍留在同一家族或同一个团体手里。','希腊 dunasteia“权势、统治”来自 dunastes“统治者”，接 dunasthai“有力量、能掌权”；经拉丁 dynastia、法语 dynastie 等路径进入英语。',DYNASTY,'the Ming dynasty 是明朝；a business dynasty 是几代人延续影响力的商业家族；a sporting dynasty 可以指连续多年强大的球队，不要求队员有血缘。','a ruling dynasty；a royal dynasty；a business dynasty；establish a dynasty。','dynasty 强调连续传承的统治或优势；empire 强调统治的范围与结构，一个帝国可以经历不同王朝。',('The exhibition includes pottery from several Chinese dynasties.','这场展览包括中国几个不同朝代的陶器。'),('The family built a publishing dynasty over three generations.','这个家族历经三代建立了一个出版业世家。'),sources=[S('dynasty'),K('dynasty'),O('dynasty')]),
E('dynastic','英 /dɪˈnæstɪk/；美 /daɪˈnæstɪk/','王朝的；与家族传承权力有关的','婚姻、继承或竞争的重点，不只是某个人得失，而是整个家族能否继续掌权。','现代可拆 dynasty + -ic，y 脱落；词源分析也有直接接希腊 dunastikos“统治者的”一说。两种分析都接 dunastes，不把英语 dynasty 画成古希腊形容词的祖先。',[['希腊 dunastes（统治者）','接 dunasthai“有力量、能够”'],['希腊 dunastikos；另一条由 dunasteia 经拉丁、法语到英语 dynasty','统治者的；王朝、掌权家族'],['英语 dynastic','可按希腊形容词借入或 dynasty + -ic 分析；王朝、家族传权相关的']],'a dynastic marriage 往往为家族权势或继承关系服务；dynastic politics 常说政治职位在同一家族内延续，不一定仍有国王。','dynastic succession；dynastic marriage；dynastic rivalry；dynastic politics。','hereditary 说某事物靠遗传或继承传下去；dynastic 更集中于掌权家族及其传承安排。',('The marriage strengthened a dynastic alliance between the two royal families.','这场婚姻巩固了两个王室家族之间的联盟。'),('The historian studies dynastic rivalries rather than individual battles.','这位历史学者研究王朝间的竞争，而非某一场战役。'),sources=[M('dynastic'),S('dynastic'),K('dynastic'),O('dynastic')]),
E('dynamite','/ˈdaɪnəmaɪt/','达纳炸药；有爆炸性影响的事物；精彩极了的〔口语〕','字面是炸药名称；比喻时说某条消息会掀起大波澜，或某次表演能量十足、效果惊人。','阿尔弗雷德·诺贝尔用希腊 dunamis“力量”加命名成分 -ite 造出瑞典语 dynamit，英语借作 dynamite。不是从现代英语 dynamo“发电机”派生。',B+[['瑞典语 dynamit，诺贝尔的命名','以“力量”命名的一种炸药'],['英语 dynamite','炸药；后来比喻爆炸性影响或精彩表现']],'历史文章可谈 dynamite 在采矿中的应用；political dynamite 指可能引爆争议的消息；The show was dynamite 是非正式赞叹。它也可作动词表示用这种炸药爆破。','political dynamite；a dynamite performance；the invention of dynamite。','explosive 是更广的爆炸物或爆炸性的；dynamite 原指特定炸药，口语的称赞义不能反过来当作化学分类。',('The museum explains how dynamite changed nineteenth-century mining.','博物馆介绍了达纳炸药如何改变十九世纪的采矿业。'),('The band’s final performance was absolute dynamite.','乐队最后那场演出精彩极了。'),sources=[S('dynamite'),K('dynamite'),O('dynamite'),'https://www.nobelprize.org/ceremonies/1996-opening-address/']),
E('dynamo','英 /ˈdaɪnəməʊ/；美 /ˈdaɪnəmoʊ/','发电机；精力充沛、能带动事情的人','机器把转动等机械能变成电能；用来形容人，就像说这个人总有源源不断的干劲。','由英语 dynamo-electric machine 缩短；完整名称对应德语 dynamo-elektrische Maschine，dynamo- 远接希腊 dunamis“力量”。现代短词不代表整个词族都源于这台机器。',B+[['近代德语 dynamo-elektrische Maschine → 英语 dynamo-electric machine','动力发电的机器名称'],['英语缩略 dynamo','发电机；比喻精力充沛的人']],'技术或历史语境常特别指直流发电机；自行车等日常名称中的用法可能较宽。a human dynamo 常是夸人精力旺、行动力强，并不是夸他会修机器。','a bicycle dynamo；a human dynamo；a dynamo of energy。','generator 是现代更通用的发电机名称；dynamo 还常保留早期设备与精力旺盛者的联想。',('A small dynamo supplies power to the bicycle’s lamp.','一个小发电机为自行车灯供电。'),('Our new organiser is a dynamo who seems to energise everyone around her.','新来的组织者精力十足，似乎能把周围所有人都带动起来。'),sources=[M('dynamo'),S('dynamo'),K('dynamo'),O('dynamo')]),
E('aerodynamics','英 /ˌeərəʊdaɪˈnæmɪks/；美 /ˌeroʊdaɪˈnæmɪks/','空气动力学；物体的空气动力特性','空气绕过机翼、球或车身时，会怎样推动、托起或阻碍它：研究的就是这一类相互作用。','aero-“空气” + dynamics“动力学”，近代英语学科构词；aero- 接希腊 aer。末尾 -s 属于学科词形，作为学科名称通常当单数。',AERO,'飞行、汽车和运动器材都能涉及 aerodynamics。the aerodynamics of a car 也可说某辆车的气动特性，不是说车本身是一门学科。','study aerodynamics；the aerodynamics of；vehicle aerodynamics。','aerodynamics 研究气流及其作用，aerodynamic 是相关形容词。它不只关心“跑得快”，也包括升力、阻力和稳定性等问题。',('Aerodynamics helps explain why a spinning ball can curve through the air.','空气动力学有助于解释旋转的球为什么会在空中拐弯。'),('The designers improved the car’s aerodynamics without making it longer.','设计师没有加长车身，却改善了汽车的气动特性。'),sources=[S('aerodynamics'),K('aerodynamics'),O('aerodynamics'),NASA]),
E('aerodynamic','英 /ˌeərəʊdaɪˈnæmɪk/；美 /ˌeroʊdaɪˈnæmɪk/','空气动力学的；气动的；有利于减小空气阻力的','有时只是说某种力或现象与气流有关；形容外形时，则常说空气更容易顺着它流过去。','现代构件是 aero- + dynamic；它与较早的学科名 aerodynamics 相配，受相关科学用语影响形成。不能把所有 aerodynamic 都直接译成“流线型”。',AERODYN,'aerodynamic forces 是气动力，未必是有利的力；an aerodynamic helmet 常强调外形减少空气阻力。一个词既可做中性的学科标签，也能在产品介绍中描述性能。','aerodynamic drag；aerodynamic forces；an aerodynamic shape；aerodynamic efficiency。','streamlined 直接说外形流畅、流线型；aerodynamic 范围更宽，压力、阻力、性能等也可以用它修饰。',('The cyclists tested a more aerodynamic helmet.','这些骑行者测试了一款更有利于减小空气阻力的头盔。'),('The wind tunnel measures the aerodynamic forces on the model.','风洞测量作用在模型上的气动力。'),sources=[K('aerodynamic'),M('aerodynamic'),S('dynamic'),NASA]),
E('aerodynamically','英 /ˌeərəʊdaɪˈnæmɪkli/；美 /ˌeroʊdaɪˈnæmɪkli/','从空气动力学角度；在气动表现上','比较外形时，专门看它与气流相处得怎么样，而不是看颜色、价格或看起来多漂亮。','aerodynamic + -ally，英语副词。常见读法中 -ically 的中间弱元音省去，末尾读 /kli/。',A(AERODYN,'英语 aerodynamic + -ally → aerodynamically','就气流作用、气动性能而言'),'aerodynamically efficient 是气动效率高；aerodynamically unstable 是气动上不稳定。副词本身不保证表现好，后面的形容词才说明评价。','aerodynamically efficient；aerodynamically stable；aerodynamically shaped。','aerodynamically 更像限定比较的维度；beautifully 评价外观或做法。看起来相似的外形也可能有不同气动表现。',('The new body is aerodynamically more efficient than the earlier design.','新车身在气动效率上比旧设计更好。'),('The two models look similar but behave differently aerodynamically.','这两个模型看起来相似，气动表现却不同。'),sources=[K('aerodynamically'),M('aerodynamically'),NASA]),
E('thermodynamic','英 /ˌθɜːməʊdaɪˈnæmɪk/；美 /ˌθɜːrmoʊdaɪˈnæmɪk/','热力学的','在看热量、能量、做功以及系统状态之间的关系；重点不是某个东西摸起来很烫。','thermo-“热” + dynamic“动力相关的”，近代英语构词；thermo- 接希腊 therme。英语形容词的记录早于 thermodynamics 这个学科名。',THERMO,'thermodynamic properties 包括理解系统状态所需的性质；a thermodynamic process 可以涉及能量变化，也可能没有热量交换。因此不把 thermo- 机械理解成“过程一定在加热”。','thermodynamic properties；a thermodynamic process；thermodynamic equilibrium；a thermodynamic cycle。','thermal 泛指热相关；thermodynamic 更明确指热力学中的状态、规律和能量关系。两个词在技术文本中不能随意互换。',('The chapter introduces the thermodynamic properties of gases.','这一章介绍气体的热力学性质。'),('The diagram represents a thermodynamic cycle used to study an engine.','这张示意图表示研究发动机时使用的一个热力循环。'),sources=[S('thermodynamic'),K('thermodynamic'),M('thermodynamic'),HEAT]),
E('thermodynamics','英 /ˌθɜːməʊdaɪˈnæmɪks/；美 /ˌθɜːrmoʊdaɪˈnæmɪks/','热力学','追踪热与功怎样参与能量转移，以及系统的温度、压力等状态如何受到影响；发动机和冰箱都能带出这类问题。','接较早的 thermodynamic，以学科词尾 -ics 形成 thermodynamics；构件可看作 thermo- + dynamics。名称虽有 -s，作学科通常用单数动词。',A(THERMO,'英语学科名 thermodynamics（-ics）','研究能量、热、功及系统状态间的关系'),'the laws of thermodynamics 是热力学定律；a course in thermodynamics 是热力学课程。它不只研究高温，冷却、制冷和没有热交换的过程也在范围内。','the laws of thermodynamics；study thermodynamics；a course in thermodynamics。','thermodynamic 是形容词，thermodynamics 是学科名；temperature 是一个物理量，不是这门学科的完整内容。',('Thermodynamics helps explain how a refrigerator moves heat from its interior.','热力学有助于解释冰箱怎样把内部的热量移走。'),('She took a course in thermodynamics before studying engine design.','她先修了热力学，再学习发动机设计。'),sources=[S('thermodynamics'),S('thermodynamic'),K('thermodynamics'),M('thermodynamics'),HEAT]),
E('hydrodynamic','英 /ˌhaɪdrəʊdaɪˈnæmɪk/；美 /ˌhaɪdroʊdaɪˈnæmɪk/','流体动力学的；水动力的','水绕着船壳或桥墩流动时，会推、拉、阻碍物体；这个形容词把话题放到这类流动与力上。','hydro-“水” + dynamic，近代英语形容词。相关学科名 hydrodynamics 经近代拉丁语进入英语，记录更早；不能把名词一律说成由这个英语形容词后来派生。',[['希腊 hudor 与 dunamikos 的构词成分','水 + 力量相关的'],['英语 hydro- + dynamic → hydrodynamic','与流动的水、液体及其作用力有关的']],'hydrodynamic resistance 是流体造成的阻力；hydrodynamic forces 是水流等作用的力。在较广的科学用法中可涉及流体，不必一看到 hydro- 就只想到自来水。','hydrodynamic forces；hydrodynamic resistance；a hydrodynamic model。','hydroelectric 说水力发电；hydrodynamic 说流体运动及力。研究一艘船受到的水阻，不等于它使用水力发电。',('The team measured the hydrodynamic resistance of the new hull.','团队测量了新船壳受到的水动力阻力。'),('The model estimates hydrodynamic forces around the bridge piers.','这个模型估算桥墩周围的水动力作用。'),sources=[S('hydrodynamic'),K('hydrodynamic'),M('hydrodynamic'),MIT]),
E('hydrodynamics','英 /ˌhaɪdrəʊdaɪˈnæmɪks/；美 /ˌhaɪdroʊdaɪˈnæmɪks/','流体动力学；水动力学','关心流体怎样流动、流动又对物体产生什么力；日常可先从水流冲过桥墩、船穿过水面来理解。','源于近代拉丁 hydrodynamica，使用希腊来源的 hydro-“水”和 dynam-“力量”；英语改为 -ics 学科词形。它有自己的较早名词借入路线，不从较晚英语 hydrodynamic 硬造祖先。',HYDRO,'hydrodynamics 常用于水或其他液体的运动研究，也能在更广的流体研究里使用。marine hydrodynamics 是海洋工程常见课程名，词尾虽有 s，学科名通常当单数。','marine hydrodynamics；the hydrodynamics of；study hydrodynamics。','hydrostatics 侧重流体静止时的情况；hydrodynamics 侧重流动与相关作用。fluid mechanics 是更宽的流体力学范围。',('The course teaches hydrodynamics through examples involving ships and waves.','这门课用船舶和波浪的例子讲授水动力学。'),('Researchers studied the hydrodynamics of water flowing around the pier.','研究者分析了水流绕过桥墩时的流动与受力情况。'),sources=[S('hydrodynamic'),K('hydrodynamics'),M('hydrodynamics'),MIT]),
E('psychodynamic','英 /ˌsaɪkəʊdaɪˈnæmɪk/；美 /ˌsaɪkoʊdaɪˈnæmɪk/','心理动力学的','这种理解人的方式会往表面反应后面看：没有说出口的感受、未察觉的动机和早期经历，可能怎样影响现在的行为。','psycho-“心理” + dynamic，十九世纪英语构词，早期广泛谈心理作用；后来在心理学中发展为特定理论与治疗取向的标签，不能把现代专义直接当成最初原义。',DYNAMIC+[['英语 psycho- + dynamic → psychodynamic','早期心理作用相关的'],['心理学中的 psychodynamic','关注无意识、情绪冲突、早期经验及关系的影响']],'a psychodynamic approach 指这一理论取向；psychodynamic therapy 是相应治疗领域用语。所谓动力是解释心理作用的比喻，不是像发动机那样测量机械功率。','a psychodynamic approach；psychodynamic theory；psychodynamic therapy；a psychodynamic interpretation。','psychological 泛指心理相关；psychodynamic 指其中较具体的一类理解方式。它是理论标签，不能当作给人的诊断名称。',('The course compares psychodynamic and cognitive approaches to personality.','这门课比较心理动力学与认知取向如何理解人格。'),('The essay offers a psychodynamic interpretation of the character’s repeated conflicts.','文章从心理动力学角度解读了这个人物反复陷入的冲突。'),sources=[S('psychodynamic'),K('psychodynamic'),M('psychodynamic'),'https://www.apa.org/depression-guideline/adults/']),
]
EXCLUDE={w:'按用户后续要求暂略：专门医学、电子学、植物学术语，或罕用王朝派生词；先保留通用阅读与基础学科的核心词。' for w in 'hemodynamic heterodyne dynast antidynastic autodyne didynamous metadynamics'.split()}
ROOT=dict(id='C0355',meaning='力量；能力；能产生作用',core='希腊 dunamis 是力量、能力。往人的状态发展是有活力，往权力发展是掌权，进入近代科学则用来谈力、运动和变化。',image='有力量 → dynamic 有活力；掌握权力 → dynasty 王朝；让能量做事 → dynamo 发电机；研究作用关系 → dynamics 动力学。',intro='先记“能起作用的力量”，再看每个词走哪条路。dynamic 不只说运动，dynasty 不等于动力，dynamics 也能说团队互动。科学复合词的前半部分告诉你正在研究空气、水流还是热与能量。',forms='dynam-、dyna-、dynamo- 都与 dunamis 这一支相关；dynast- 经 dunastes“统治者”走向家族掌权。-ics 常构成学科名。各词并非都从现代英语 dynamic 加尾巴形成，尤其 dynamics 与 hydrodynamics 有较早的学科词史。',branches=[['活力、变化与互动','dynamic, dynamics, dynamically, dynamical, dynamism'],['掌权的家族与传承','dynasty, dynastic'],['强力的名称与比喻','dynamite, dynamo'],['气流及其作用','aerodynamics, aerodynamic, aerodynamically'],['热、能量与做功','thermodynamic, thermodynamics'],['水流、流体与作用力','hydrodynamic, hydrodynamics'],['心理理论与特定农法','psychodynamic, biodynamic']],contrasts='dynamic 说有活力或变化，dynamical 多用于技术语境；dynamics 可说动力学，也可说群体互动。dynasty 属于权力传承支线。biodynamic farming 是具体农法名称，不能仅凭 bio + dynamic 就解释成普通“有生命力的农业”。',practice='The dynamic team studied the aerodynamics of the new car. 一个有活力的团队研究新车的气动表现：同一个力量来源，在形容人和谈科学时各有具体含义。',words=[],exclude=EXCLUDE)
